      message: 'Tin nhắn đã là tiếng Việt nên không cần dịch.' }, base),
  };
}
return { json: { ok: errors.length === 0, plan, errors, early, targetLanguage, targetLanguageName: targetLanguage ? langName(targetLanguage) : null, storedLanguage } };

