const VI_ONLY = /[ăắằẳẵặơớờởỡợưứừửữựđạảậẩẫấầẹẻẽệểễếềịỉĩọỏộổỗốồụủũỵỷỹỳ]/giu;
const VI_WORDS = /(?<![\p{L}])(tôi|không|của|được|chúng tôi|cảm ơn|xin chào|vâng|nhé|bạn|muốn|cần|giúp|báo giá|dịch vụ|sản phẩm|khách hàng)(?![\p{L}])/giu;
const looksVietnamese = (t) => {
  const str = String(t).normalize('NFC');
  const letters = (str.match(VI_ONLY) || []).length;
  const words = (str.match(VI_WORDS) || []).length;
  return letters >= 2 || (letters >= 1 && words >= 1) || words >= 2;
};

// WF-12 | Stage 3/6/7 - đọc câu trả lời của Gemini, kiểm tra, chuẩn hóa, quyết định "đạt" hay "cần người xem lại".
const MIN_CONFIDENCE = 0.6;   // AI tự chấm dưới mức này => needs_review (vẫn lưu bản dịch nhưng KHÔNG ghi nhớ ngôn ngữ của khách)
const v = $('03 Validate Input').item.json;
const p = $('07 Plan Translation').item.json;
const model = $('10 Build AI Request').item.json.model;
const r = $json;

const fail = (code, message, httpCode, logStatus) => ({ json: { ok: false, errors: [{ code, message }], httpCode, logStatus, provider: { name: 'gemini', model } } });

const block = safe(() => r.promptFeedback.blockReason, null);
if (block) return fail('BLOCKED_BY_PROVIDER', 'Nhà cung cấp AI từ chối xử lý nội dung này (' + block + ')', 422, 'rejected');
const cand = safe(() => r.candidates[0], null);
const raw = safe(() => cand.content.parts.map((x) => x.text || '').join(''), '').trim();
if (!raw) return fail('EMPTY_AI_RESPONSE', 'AI không trả về nội dung', 502, 'failed');
if (safe(() => cand.finishReason, '') === 'MAX_TOKENS') return fail('AI_TRUNCATED', 'Câu trả lời của AI bị cắt giữa chừng', 502, 'failed');
let j;
try { j = JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g, '')); } catch (e) { return fail('AI_BAD_JSON', 'AI trả về dữ liệu không phải JSON hợp lệ', 502, 'failed'); }
if (!j || typeof j !== 'object') return fail('AI_BAD_JSON', 'AI trả về dữ liệu không đúng khuôn', 502, 'failed');

const translated = s(j.translation, 8000);
if (!translated) return fail('EMPTY_TRANSLATION', 'AI không trả về bản dịch', 502, 'failed');

let code = s(j.languageCode, 20).toLowerCase().split(/[-_]/)[0];
if (!/^[a-z]{2,3}$/.test(code)) code = 'und';
let confidence = Number(j.confidence);
confidence = Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0;

const reasons = [];
if (v.direction === 'inbound') {
  if (code === 'und') reasons.push('LANGUAGE_UNDETECTED');
} else {
  if (code !== p.targetLanguage) reasons.push('TARGET_MISMATCH');
  if (translated.replace(/\s+/g, ' ').trim() === v.text.replace(/\s+/g, ' ').trim()) reasons.push('NOT_TRANSLATED');
  code = p.targetLanguage;
}
if (confidence < MIN_CONFIDENCE) reasons.push('LOW_CONFIDENCE');

const needsTranslation = !(v.direction === 'inbound' && code === 'vi');
const status = reasons.length ? 'needs_review' : 'translated';
const lang = { code, name: s(j.languageName, 60) || (code === 'und' ? 'Unknown' : langName(code)) };

const translation = {
  schemaVersion: 1, workflow: 'WF-12', direction: v.direction, status, needsTranslation,
  language: v.direction === 'inbound' ? lang : { code: 'vi', name: 'Vietnamese' },
  targetLanguage: v.direction === 'outbound' ? lang : { code: 'vi', name: 'Vietnamese' },
  translatedText: needsTranslation ? translated : v.text,
  backTranslation: v.direction === 'outbound' ? (s(j.backTranslation, 8000) || null) : null,
  confidence, needsReview: reasons.length > 0, reviewReasons: reasons, notes: s(j.notes, 300) || null, truncated: v.warnings.includes('TEXT_TRUNCATED'),
  provider: { name: 'gemini', model }, translatedAt: new Date().toISOString(), correlationId: v.correlationId, n8nExecutionId: String($execution.id),
};
// Ghi nhớ ngôn ngữ của khách vào leads.metadata.language: chỉ khi tin của khách, có lead, kết quả đáng tin, không phải tiếng Việt và khác ngôn ngữ đang lưu.
const remember = v.direction === 'inbound' && !!v.leadId && status === 'translated' && code !== 'vi' && code !== 'und' && code !== p.storedLanguage;
return { json: { ok: true, status, translation, remember, language: { code, name: lang.name, source: 'wf12', confidence, detectedAt: translation.translatedAt }, provider: translation.provider } };

