  const words = (str.match(VI_WORDS) || []).length;
  return letters >= 2 || (letters >= 1 && words >= 1) || words >= 2;
};

// WF-12 | Stage 8 - Transformation: dựng sự kiện message.translated / reply.translated và phản hồi cuối cho người gọi.
const v = $('03 Validate Input').item.json;
const p = $('07 Plan Translation').item.json;
const a = $('12 Parse and Validate Result').item.json;
const t = a.translation;
const interactionId = $json.interaction_id || null;
const remembered = !!$json.language_remembered;

const message = a.status === 'needs_review'
  ? 'Đã dịch nhưng cần người xem lại (' + t.reviewReasons.join(', ') + '). Chưa ghi nhớ ngôn ngữ của khách.'
  : (!t.needsTranslation ? 'Tin nhắn đã là tiếng Việt nên không cần dịch.'
    : (v.direction === 'inbound'
      ? 'Đã nhận diện ngôn ngữ ' + t.language.name + ' và dịch sang tiếng Việt' + (remembered ? '; đã ghi nhớ ngôn ngữ của khách.' : '.')
      : 'Đã dịch câu trả lời sang ' + t.targetLanguage.name + '. Hãy kiểm tra "dịch ngược" trước khi gửi cho khách.'));

const response = {
  status: a.status, correlationId: v.correlationId, direction: v.direction, interactionId, leadId: v.leadId || null,
  language: t.language, targetLanguage: t.targetLanguage, translatedText: t.translatedText, backTranslation: t.backTranslation,
  confidence: t.confidence, needsReview: t.needsReview, reviewReasons: t.reviewReasons, notes: t.notes, languageRemembered: remembered,
  saved: !!interactionId, message,
};
const out = { response, hasEntity: !!interactionId, eventBody: null };
if (interactionId) {
  out.eventBody = {
    eventName: v.direction === 'inbound' ? 'message.translated' : 'reply.translated',
    aggregateType: 'interaction', aggregateId: interactionId, organizationId: v.organizationId, correlationId: v.correlationId,
    payload: {
      schemaVersion: 1, workflow: 'WF-12', direction: v.direction, interactionId, leadId: v.leadId || null, sourceEventId: v.eventId,
      channel: v.channel, language: t.language, targetLanguage: t.targetLanguage, translatedText: t.translatedText.slice(0, 1500),
      confidence: t.confidence, needsReview: t.needsReview, languageRemembered: remembered, provider: t.provider,
    },
  };
}
return { json: out };

